/**
 * What to do when a new note's name is taken.
 */

public enum Collision: Equatable, Hashable {
    
    /**
     * Refuse, so the caller can prompt.
     */
    case fail
    /**
     * Append ` (1)`, ` (2)`, … until a free name is found.
     */
    case rename
    /**
     * Replace. Only for a caller that has already asked.
     */
    case overwrite





}

#if compiler(>=6)
extension Collision: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCollision: FfiConverterRustBuffer {
    typealias SwiftType = Collision

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Collision {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .fail
        
        case 2: return .rename
        
        case 3: return .overwrite
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Collision, into buf: inout [UInt8]) {
        switch value {
        
        
        case .fail:
            writeInt(&buf, Int32(1))
        
        
        case .rename:
            writeInt(&buf, Int32(2))
        
        
        case .overwrite:
            writeInt(&buf, Int32(3))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
