/**
 * A non-fatal problem found while scanning. Collected and reported together,
 * because a vault with a hundred case collisions deserves one report.
 */

public enum Diagnostic: Equatable, Hashable {
    
    /**
     * Two names differing only by case. Fine on ext4; on the volume iOS ships
     * with, one of them shadows the other.
     */
    case caseConflict(paths: [VaultPath]
    )
    /**
     * A name Windows would reject, in a vault authored elsewhere.
     */
    case unportableName(path: VaultPath, reason: String
    )
    /**
     * A leftover `.ie-tmp-*`: a previous write was interrupted.
     */
    case interruptedWrite(path: VaultPath
    )
    /**
     * Unreadable, so left untouched and excluded rather than treated as empty.
     */
    case unreadableFile(path: VaultPath, message: String
    )
    /**
     * Frontmatter that is not valid YAML. Still indexed for text and links.
     */
    case malformedFrontmatter(path: VaultPath, message: String
    )
    /**
     * A symlink pointing out of the vault. Not followed.
     */
    case escapingSymlink(path: VaultPath
    )





}

#if compiler(>=6)
extension Diagnostic: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDiagnostic: FfiConverterRustBuffer {
    typealias SwiftType = Diagnostic

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Diagnostic {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .caseConflict(paths: try FfiConverterSequenceTypeVaultPath.read(from: &buf)
        )
        
        case 2: return .unportableName(path: try FfiConverterTypeVaultPath.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .interruptedWrite(path: try FfiConverterTypeVaultPath.read(from: &buf)
        )
        
        case 4: return .unreadableFile(path: try FfiConverterTypeVaultPath.read(from: &buf), message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .malformedFrontmatter(path: try FfiConverterTypeVaultPath.read(from: &buf), message: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .escapingSymlink(path: try FfiConverterTypeVaultPath.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Diagnostic, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .caseConflict(paths):
            writeInt(&buf, Int32(1))
            FfiConverterSequenceTypeVaultPath.write(paths, into: &buf)
            
        
        case let .unportableName(path,reason):
            writeInt(&buf, Int32(2))
            FfiConverterTypeVaultPath.write(path, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .interruptedWrite(path):
            writeInt(&buf, Int32(3))
            FfiConverterTypeVaultPath.write(path, into: &buf)
            
        
        case let .unreadableFile(path,message):
            writeInt(&buf, Int32(4))
            FfiConverterTypeVaultPath.write(path, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .malformedFrontmatter(path,message):
            writeInt(&buf, Int32(5))
            FfiConverterTypeVaultPath.write(path, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .escapingSymlink(path):
            writeInt(&buf, Int32(6))
            FfiConverterTypeVaultPath.write(path, into: &buf)
            
        }
    }
}


