/**
 * Everything the bridge can fail with.
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case NoVaultOpen
    case OutsideVault(path: String
    )
    case NotFound(path: String
    )
    case AlreadyExists(path: String
    )
    case NotANote(path: String
    )
    /**
     * A name differing only by capitalisation from something already there.
     * Legal on a case-sensitive volume, silently destructive on the
     * case-insensitive one iOS ships with, so it is refused on both.
     */
    case CaseCollision(requested: String, existing: String
    )
    case InvalidName(name: String, reason: String
    )
    case AmbiguousLink(target: String, candidates: String
    )
    case InvalidFrontmatter(path: String, message: String
    )
    case InvalidQuery(message: String
    )
    case IndexCorrupt(message: String
    )
    case Index(message: String
    )
    case Unsupported(operation: String
    )
    case Platform(code: String, message: String
    )
    case Refused(operation: String, reason: String
    )
    /**
     * The file changed underneath an open buffer.
     *
     * Not a core error, because the desktop resolves it differently: the
     * file may have been edited in the Files app, by iCloud, or by a desktop
     * client syncing the same folder. The only correct response is to ask,
     * which is why this exists as its own variant rather than as a `Refused`
     * the UI would have to read the prose of.
     */
    case ExternalModification(path: String, 
        /**
         * When the buffer was loaded.
         */openedModifiedMs: Int64, 
        /**
         * What the file says now.
         */currentModifiedMs: Int64
    )
    /**
     * The host handed the bridge something it could not use — a path that
     * escapes the vault, a malformed property value.
     */
    case InvalidArgument(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NoVaultOpen
        case 2: return .OutsideVault(
            path: try FfiConverterString.read(from: &buf)
            )
        case 3: return .NotFound(
            path: try FfiConverterString.read(from: &buf)
            )
        case 4: return .AlreadyExists(
            path: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NotANote(
            path: try FfiConverterString.read(from: &buf)
            )
        case 6: return .CaseCollision(
            requested: try FfiConverterString.read(from: &buf), 
            existing: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidName(
            name: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 8: return .AmbiguousLink(
            target: try FfiConverterString.read(from: &buf), 
            candidates: try FfiConverterString.read(from: &buf)
            )
        case 9: return .InvalidFrontmatter(
            path: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 10: return .InvalidQuery(
            message: try FfiConverterString.read(from: &buf)
            )
        case 11: return .IndexCorrupt(
            message: try FfiConverterString.read(from: &buf)
            )
        case 12: return .Index(
            message: try FfiConverterString.read(from: &buf)
            )
        case 13: return .Unsupported(
            operation: try FfiConverterString.read(from: &buf)
            )
        case 14: return .Platform(
            code: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )
        case 15: return .Refused(
            operation: try FfiConverterString.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 16: return .ExternalModification(
            path: try FfiConverterString.read(from: &buf), 
            openedModifiedMs: try FfiConverterInt64.read(from: &buf), 
            currentModifiedMs: try FfiConverterInt64.read(from: &buf)
            )
        case 17: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .NoVaultOpen:
            writeInt(&buf, Int32(1))
        
        
        case let .OutsideVault(path):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .NotFound(path):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .AlreadyExists(path):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .NotANote(path):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(path, into: &buf)
            
        
        case let .CaseCollision(requested,existing):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(requested, into: &buf)
            FfiConverterString.write(existing, into: &buf)
            
        
        case let .InvalidName(name,reason):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(name, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .AmbiguousLink(target,candidates):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(target, into: &buf)
            FfiConverterString.write(candidates, into: &buf)
            
        
        case let .InvalidFrontmatter(path,message):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(path, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidQuery(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .IndexCorrupt(message):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Index(message):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Unsupported(operation):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(operation, into: &buf)
            
        
        case let .Platform(code,message):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Refused(operation,reason):
            writeInt(&buf, Int32(15))
            FfiConverterString.write(operation, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .ExternalModification(path,openedModifiedMs,currentModifiedMs):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(path, into: &buf)
            FfiConverterInt64.write(openedModifiedMs, into: &buf)
            FfiConverterInt64.write(currentModifiedMs, into: &buf)
            
        
        case let .InvalidArgument(message):
            writeInt(&buf, Int32(17))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


