/**
 * A frontmatter value, with its type preserved.
 *
 * `Object` carries a list of entries rather than a map: the core uses a
 * `BTreeMap` so YAML keys keep a stable order, and a map across the FFI
 * boundary would lose that ordering on the Swift side. A list keeps it, and
 * keeps round-tripping a note's frontmatter byte-stable.
 */

public indirect enum PropertyValue: Equatable, Hashable {
    
    case text(value: String
    )
    case number(value: Double
    )
    case checkbox(value: Bool
    )
    /**
     * A calendar date with no time, `2026-09-17`.
     */
    case date(value: String
    )
    /**
     * An instant, RFC 3339.
     */
    case dateTime(value: String
    )
    case list(values: [PropertyValue]
    )
    case object(entries: [Property]
    )
    case null





}

#if compiler(>=6)
extension PropertyValue: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePropertyValue: FfiConverterRustBuffer {
    typealias SwiftType = PropertyValue

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PropertyValue {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .text(value: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .number(value: try FfiConverterDouble.read(from: &buf)
        )
        
        case 3: return .checkbox(value: try FfiConverterBool.read(from: &buf)
        )
        
        case 4: return .date(value: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .dateTime(value: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .list(values: try FfiConverterSequenceTypePropertyValue.read(from: &buf)
        )
        
        case 7: return .object(entries: try FfiConverterSequenceTypeProperty.read(from: &buf)
        )
        
        case 8: return .null
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PropertyValue, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .text(value):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(value, into: &buf)
            
        
        case let .number(value):
            writeInt(&buf, Int32(2))
            FfiConverterDouble.write(value, into: &buf)
            
        
        case let .checkbox(value):
            writeInt(&buf, Int32(3))
            FfiConverterBool.write(value, into: &buf)
            
        
        case let .date(value):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(value, into: &buf)
            
        
        case let .dateTime(value):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(value, into: &buf)
            
        
        case let .list(values):
            writeInt(&buf, Int32(6))
            FfiConverterSequenceTypePropertyValue.write(values, into: &buf)
            
        
        case let .object(entries):
            writeInt(&buf, Int32(7))
            FfiConverterSequenceTypeProperty.write(entries, into: &buf)
            
        
        case .null:
            writeInt(&buf, Int32(8))
        
        }
    }
}


